import React, { useState, useEffect } from 'react';
import { Card, api } from '../App';

export default function LabelsPage() {
  const [saleNos,     setSaleNos]     = useState([]);
  const [selSale,     setSelSale]     = useState('');
  const [markings,    setMarkings]    = useState([]);
  const [histPrices,  setHistPrices]  = useState({});
  const [prevSaleNos, setPrevSaleNos] = useState([]);
  const [loading,     setLoading]     = useState(false);
  const [showHist,    setShowHist]    = useState(true);
  const [prevSales,   setPrevSales]   = useState(2);
  const [filterParty, setFilterParty] = useState('');
  const [filterGrade, setFilterGrade] = useState('');

  useEffect(() => {
    api.get('/import/sale-numbers')
      .then(r => { setSaleNos(r.data); if (r.data[0]) setSelSale(String(r.data[0].sale_no)); })
      .catch(() => {});
  }, []);

  const load = async (sale, pSales) => {
    if (!sale) return;
    setLoading(true);
    try {
      const [mRes, hRes] = await Promise.all([
        api.get(`/labels/markings?sale_no=${sale}`),
        api.get(`/labels/historical-prices?sale_no=${sale}&prev_sales=${pSales || prevSales}`)
      ]);
      setMarkings(mRes.data || []);
      setHistPrices(hRes.data.lookup || {});
      setPrevSaleNos(hRes.data.prev_sale_nos || []);
    } catch (e) { console.error(e); }
    finally { setLoading(false); }
  };

  const handleSaleChange = s => { setSelSale(s); load(s, prevSales); };
  const handlePrevChange = n => { setPrevSales(n); if (selSale) load(selSale, n); };

  const seen = new Set();
  const unique = markings.filter(m => {
    const k = `${m.party_code}__${m.garden}__${m.grade}`;
    if (seen.has(k)) return false;
    seen.add(k); return true;
  });

  const parties = [...new Set(unique.map(m => m.party_code))].sort();
  const grades  = [...new Set(unique.map(m => m.grade))].sort();
  const filtered = unique.filter(m =>
    (!filterParty || m.party_code === filterParty) &&
    (!filterGrade || m.grade === filterGrade)
  );

  const fmtDate = d => {
    if (!d) return '';
    try {
      const dt = new Date(d);
      return `${String(dt.getDate()).padStart(2,'0')}/${String(dt.getMonth()+1).padStart(2,'0')}`;
    } catch { return ''; }
  };

  const printLabels = () => {
    const win = window.open('', '_blank');

    const labelsHtml = filtered.map(m => {
      const histData = histPrices[`${m.garden}__${m.grade}`];
      const gpDate   = fmtDate(m.gp_date);

      // Build per-sale LSP lines: "Sl.14-291/-" or "Sl.13-112-130"
      let histLine = '';
      if (showHist && histData && histData.sales && histData.sales.length > 0) {
        const parts = histData.sales.map(s => {
          const lo = s.price_low, hi = s.price_high;
          const priceStr = lo === hi ? `${lo}/-` : `${lo}-${hi}`;
          return `S⁄${s.sale_no}-${priceStr}`;
        });
        histLine = `<div class="hist">${parts.join(' | ')}</div>`;
      }

      return `<div class="lbl">
  <div class="r1">
    <b>${m.party_code}</b><span class="d">|</span>S${m.sale_no}<span class="d">|</span><b>${m.lot_no || ''}</b><span class="d">|</span><span class="grd">${m.grade}</span>
  </div>
  <div class="r2">
    <b class="inv">${m.invoice_raw || m.invoice || ''}</b><span class="d">|</span><span>${m.bags || '?'}&#215;${m.net_wt || '?'}</span>${gpDate ? `<span class="d">|</span><span>${gpDate}</span>` : ''}
  </div>
  <div class="gname">${m.garden}</div>
  <div class="orig">${m.origin || ''}</div>
  ${histLine}
</div>`;
    }).join('');

    win.document.write(`<!DOCTYPE html>
<html><head><title>Labels Sale #${selSale}</title>
<style>
*{margin:0;padding:0;box-sizing:border-box;}
body{font-family:Arial,Helvetica,sans-serif;}
@page{size:A4 portrait;margin:5mm;}
.grid{
  display:grid;
  grid-template-columns:repeat(4,47.5mm);
  grid-auto-rows:23mm;
  gap:0;
  width:190mm;
  border-top: 0.3pt dashed #ccc;
  border-left: 0.3pt dashed #ccc;
}
.lbl{
  width:47.5mm;height:23mm;
  border:none;
  border-bottom: 0.3pt dashed #ccc;
  border-right: 0.3pt dashed #ccc;
  padding:1mm 2mm 0.8mm 2.5mm;
  overflow:hidden;
  display:flex;flex-direction:column;
  justify-content:space-between;
  page-break-inside:avoid;
}
.r1{font-size:7.5pt;display:flex;align-items:center;gap:1mm;border-bottom:0.3pt solid #ddd;padding-bottom:0.4mm;white-space:nowrap;overflow:hidden;}
.r1 b{font-weight:900;font-size:8pt;}
.r2{font-size:6.5pt;display:flex;align-items:center;gap:1mm;white-space:nowrap;overflow:hidden;}
.r3{font-size:6.5pt;display:flex;align-items:center;gap:1.5mm;font-weight:600;color:#222;}
.d{color:#bbb;font-size:5.5pt;}
.inv{font-size:7pt;font-weight:900;color:#000;}
.grd{background:#1e3a8a;color:#fff;padding:0.2mm 1.5mm;border-radius:2mm;font-size:6pt;font-weight:900;}
.gname{font-size:7.5pt;font-weight:900;color:#000;text-transform:uppercase;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;letter-spacing:0.2pt;}
.orig{font-size:5pt;color:#666;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.hist{font-size:5.5pt;font-weight:700;color:#92400e;background:#fffbeb;border-top:0.3pt solid #fde68a;padding-top:0.4mm;white-space:nowrap;overflow:hidden;}
@media print{body{-webkit-print-color-adjust:exact;print-color-adjust:exact;}.lbl{page-break-inside:avoid;}}
</style></head><body>
<div class="grid">${labelsHtml}</div>
</body></html>`);
    win.document.close();
    win.focus();
    setTimeout(() => { win.print(); win.close(); }, 500);
  };

  const previewCard = (m, i) => {
    const histData = histPrices[`${m.garden}__${m.grade}`];
    const gpDate   = fmtDate(m.gp_date);
    const s = { flexShrink: 0 };

    // Build per-sale LSP text
    let histText = null;
    if (showHist && histData && histData.sales && histData.sales.length > 0) {
      histText = histData.sales.map(sale => {
        const lo = sale.price_low, hi = sale.price_high;
        return `S⁄${sale.sale_no}-${lo === hi ? lo + '/-' : lo + '-' + hi}`;
      }).join(' | ');
    }

    return (
      <div key={i} style={{ width: 192, height: histText ? 100 : 88, border: '1px dashed #ccc', borderTop: 'none', borderLeft: 'none', padding: '4px 10px 4px 8px', display: 'flex', flexDirection: 'column', justifyContent: 'space-between', background: '#fff', overflow: 'hidden' }}>
        {/* Row 1: PartyCode | Sale | LotNo (bold) | Grade */}
        <div style={{ display: 'flex', alignItems: 'center', gap: 4, borderBottom: '1px solid #e5e7eb', paddingBottom: 3, ...s }}>
          <span style={{ fontWeight: 900, fontSize: 11 }}>{m.party_code}</span>
          <span style={{ color: '#ccc', fontSize: 8 }}>|</span>
          <span style={{ fontSize: 9, color: '#555' }}>S{m.sale_no}</span>
          <span style={{ color: '#ccc', fontSize: 8 }}>|</span>
          <span style={{ fontWeight: 900, fontSize: 11, color: '#1a3c5e' }}>{m.lot_no || ''}</span>
          <span style={{ color: '#ccc', fontSize: 8 }}>|</span>
          <span style={{ background: '#1e3a8a', color: '#fff', padding: '1px 5px', borderRadius: 8, fontSize: 8, fontWeight: 900 }}>{m.grade}</span>
        </div>
        {/* Row 2: Invoice (bold) | Bags×Wt | Date */}
        <div style={{ display: 'flex', alignItems: 'center', gap: 4, fontSize: 9, ...s }}>
          <span style={{ fontWeight: 900, fontSize: 10, color: '#222' }}>{m.invoice_raw || m.invoice || ''}</span>
          <span style={{ color: '#ccc' }}>|</span>
          <span style={{ fontWeight: 600, color: '#374151' }}>{m.bags || '?'}×{m.net_wt || '?'}</span>
          {gpDate && <><span style={{ color: '#ccc' }}>|</span><span style={{ color: '#555' }}>{gpDate}</span></>}
        </div>
        {/* Garden */}
        <div style={{ fontWeight: 900, fontSize: 11, color: '#000', textTransform: 'uppercase', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis', letterSpacing: 0.3, ...s }}>
          {m.garden}
        </div>
        {/* Origin */}
        <div style={{ fontSize: 8, color: '#6b7280', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis', ...s }}>
          {m.origin || ''}
        </div>
        {/* Per-sale LSP */}
        {histText && (
          <div style={{ fontSize: 8, fontWeight: 700, color: '#92400e', background: '#fffbeb', borderTop: '1px solid #fde68a', paddingTop: 2, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis', ...s }}>
            {histText}
          </div>
        )}
      </div>
    );
  };

  return (
    <div>
      <h2 style={{ marginBottom: 2, color: '#1a3c5e', fontSize: 20, fontWeight: 800 }}>🏷 Print Labels</h2>
      <p style={{ color: '#9ca3af', fontSize: 12, marginBottom: 14 }}>
        48 labels per A4 — 4 columns × 12 rows (47.5mm × 23mm). Matches standard tea auction label format.
      </p>

      <Card style={{ marginBottom: 14, padding: 14 }}>
        <div style={{ display: 'flex', gap: 14, alignItems: 'flex-start', flexWrap: 'wrap' }}>
          <div>
            <label style={{ display: 'block', fontSize: 10, fontWeight: 700, color: '#6b7280', marginBottom: 4, textTransform: 'uppercase' }}>Sale Number</label>
            <select value={selSale} onChange={e => handleSaleChange(e.target.value)}
              style={{ padding: '7px 12px', border: '1.5px solid #cbd5e0', borderRadius: 6, fontSize: 13, minWidth: 200 }}>
              <option value="">Select sale...</option>
              {saleNos.map(s => <option key={s.sale_no} value={s.sale_no}>Sale {s.sale_no} ({s.lot_count} lots)</option>)}
            </select>
          </div>

          <div style={{ padding: '10px 14px', background: '#fffbeb', border: '1px solid #fde68a', borderRadius: 8 }}>
            <div style={{ fontSize: 11, fontWeight: 700, color: '#92400e', marginBottom: 6 }}>📊 Historical LSP on Label</div>
            <label style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 6, cursor: 'pointer' }}>
              <input type="checkbox" checked={showHist} onChange={e => setShowHist(e.target.checked)} style={{ width: 14, height: 14 }} />
              <span style={{ fontSize: 12, fontWeight: 600, color: '#92400e' }}>Show Last Sold Price from prev sales</span>
            </label>
            {showHist && (
              <div>
                <div style={{ fontSize: 10, color: '#b45309', marginBottom: 4, fontWeight: 600 }}>No. of previous sales:</div>
                <div style={{ display: 'flex', gap: 5 }}>
                  {[1,2,3,4].map(n => (
                    <button key={n} onClick={() => handlePrevChange(n)}
                      style={{ padding: '3px 10px', borderRadius: 4, fontSize: 11, fontWeight: 700, cursor: 'pointer',
                        background: prevSales === n ? '#f59e0b' : '#fef3c7',
                        color: prevSales === n ? '#fff' : '#92400e',
                        border: `1.5px solid ${prevSales === n ? '#f59e0b' : '#fde68a'}` }}>{n}</button>
                  ))}
                </div>
                {prevSaleNos.length > 0 && (
                  <div style={{ fontSize: 9, color: '#b45309', marginTop: 4 }}>Using Sale {prevSaleNos.join(', ')}</div>
                )}
              </div>
            )}
          </div>

          <div>
            <label style={{ display: 'block', fontSize: 10, fontWeight: 700, color: '#6b7280', marginBottom: 4, textTransform: 'uppercase' }}>Party</label>
            <select value={filterParty} onChange={e => setFilterParty(e.target.value)}
              style={{ padding: '6px 10px', border: '1.5px solid #cbd5e0', borderRadius: 5, fontSize: 12, minWidth: 140 }}>
              <option value="">All Parties</option>
              {parties.map(p => <option key={p} value={p}>{p}</option>)}
            </select>
          </div>
          <div>
            <label style={{ display: 'block', fontSize: 10, fontWeight: 700, color: '#6b7280', marginBottom: 4, textTransform: 'uppercase' }}>Grade</label>
            <select value={filterGrade} onChange={e => setFilterGrade(e.target.value)}
              style={{ padding: '6px 10px', border: '1.5px solid #cbd5e0', borderRadius: 5, fontSize: 12, minWidth: 110 }}>
              <option value="">All Grades</option>
              {grades.map(g => <option key={g} value={g}>{g}</option>)}
            </select>
          </div>
        </div>

        {filtered.length > 0 && (
          <div style={{ marginTop: 14, display: 'flex', alignItems: 'center', gap: 12 }}>
            <button onClick={printLabels}
              style={{ padding: '8px 22px', background: '#1a3c5e', color: '#fff', border: 'none', borderRadius: 6, cursor: 'pointer', fontWeight: 700, fontSize: 13 }}>
              🖨 Print {filtered.length} Labels ({Math.ceil(filtered.length / 48)} page{filtered.length > 48 ? 's' : ''})
            </button>
            <span style={{ fontSize: 11, color: '#6b7280' }}>4 cols × 12 rows · 47.5×23mm · 48 per A4</span>
          </div>
        )}
      </Card>

      {loading && <Card style={{ padding: 30, textAlign: 'center', color: '#888' }}>⏳ Loading...</Card>}
      {!loading && !filtered.length && selSale && (
        <Card style={{ padding: 30, textAlign: 'center', color: '#aaa' }}>No markings for Sale #{selSale}. Create markings first.</Card>
      )}

      {!loading && filtered.length > 0 && (
        <div>
          <div style={{ fontSize: 12, color: '#6b7280', marginBottom: 10, fontWeight: 600 }}>
            Preview — {filtered.length} labels
            <span style={{ fontSize: 10, fontWeight: 400, marginLeft: 8, color: '#9ca3af' }}>(screen preview enlarged for readability)</span>
          </div>
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6 }}>
            {filtered.map((m, i) => previewCard(m, i))}
          </div>
        </div>
      )}
    </div>
  );
}
